sp_widget.client_script:
function loginCtrl($scope, $http, $window, $location, spUtil) {
  var c = this;
  c.loading = false;
  c.message = '';

  c.focusPassword = function() {
    var el = document.getElementById('password');
    if (el) el.focus();
  };

  c.login = function(username, password) {
    if (!username || !password) {
      c.message = 'Please enter your username and password.';
      return;
    }

    c.loading = true;
    c.message = '';
    var url = spUtil.getURL({ sysparm_type: 'view_form.login' });

    return $http({
      method: 'post',
      url: url,
      data: $.param({
        'sysparm_type': 'login',
        'user_name': username,
        'user_password': password,
        'remember_me': false,
        'get_redirect_url': true,
        'is_direct_redirect': true
      }),
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
    }).then(function(response) {
      c.loading = false;
      if (!response.data) {
        c.message = 'There was an error processing your request.';
        return;
      }
      if (response.data.status === 'success') {
        $window.location = response.data.redirect_url;
      } else if (response.data.status === 'mfa_code_required') {
        $window.location = '/validate_multifactor_auth_code.do';
      } else {
        c.message = response.data.message || 'Invalid username or password.';
        c.password = '';
        c.username = '';
        var el = document.getElementById('username');
        if (el) el.focus();
      }
    }, function() {
      c.loading = false;
      c.message = 'There was an error processing your request.';
    });
  };

  c.externalLogin = function() {
    $window.location = '/login_with_sso.do';
  };
}

sp_widget.css:
* {
  box-sizing: border-box;
}

/* Force loaded Google Fonts over any portal theme defaults */
.clm-login-viewport,
.clm-login-viewport h1,
.clm-login-viewport h2,
.clm-login-viewport p,
.clm-login-viewport span,
.clm-login-viewport input,
.clm-login-viewport button {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
}

.clm-login-viewport {
  position: relative;
  width: 100%;
  height: 100vh;
  margin: 0;
  padding: 70px 80px; /* Increased vertical height & breathing room */
  background-color: #f7f9fa;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Background Artwork */
.clm-bg-art {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.clm-bg-art svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* Container */
.clm-login-container {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1240px;
  min-height: 640px; /* Increased height of the container */
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 56px;
}

/* ================= LEFT COLUMN ================= */
.clm-info-section {
  flex: 1.15;
  max-width: 580px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.clm-brand-header {
  margin-bottom: 28px;
}

/* Logo Integration */
.clm-logo-wrap {
  display: inline-block;
  background: transparent !important;
}

.clm-brand-logo {
  max-width: 180px;
  height: auto;
  display: block;
  background: transparent !important;
  mix-blend-mode: multiply;
}

.clm-brand-divider {
  width: 44px;
  height: 4px;
  background-color: #ffd800;
  border-radius: 2px;
  margin-bottom: 22px;
}

/* Hierarchy:
   1. "Enable" (clm-headline) -> 900
   2. "Credit Limit" (clm-kicker) -> 700
   3. "Streamline" (clm-subtext) -> 500
*/
.clm-headline {
  font-size: 42px;
  font-weight: 900 !important;
  line-height: 1.22;
  color: #000000 !important;
  margin: 0 0 18px;
  letter-spacing: -0.02em;
}

.clm-kicker {
  font-size: 13px;
  font-weight: 700 !important;
  color: #334155;
  letter-spacing: 0.05em;
  word-spacing: 0.15em;
  margin-bottom: 12px;
  text-transform: uppercase;
}

.clm-subtext {
  font-size: 20px;
  font-weight: 300;
  line-height: 2.1;
  color: #556274;
  margin: 0 0 46px;
  letter-spacing: 0.005em;
}

/* Feature Columns: Exact width match with the left text container & equal column distribution */
.clm-features-row {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 48px;
}

.clm-feature-col {
  display: flex;
  flex-direction: column;
  align-items: center; /* Center-align icon and text */
  justify-content: center;
  flex: 1; /* Equal spacing across the row */
  text-align: center;
}

/* Enlarged SVG Icons */
.clm-feature-icon {
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0f172a;
  margin-bottom: 10px;
}

.clm-feature-icon svg {
  width: 42px !important;
  height: 42px !important;
  display: block;
}

.clm-feature-label {
  font-size: 13.5px;
  font-weight: 700 !important;
  color: #0f172a;
  letter-spacing: 0.01em;
}

/* Center-aligned vertical divider */
.clm-feature-sep {
  width: 1px;
  height: 44px;
  background-color: #cbd5e1;
  align-self: center;
  flex-shrink: 0;
}

/* Copyright text */
.clm-copyright-desktop {
  font-size: 12.5px;
  font-weight: 400 !important;
  color: #94a3b8;
}

.clm-copyright-mobile {
  display: none;
}

/* ================= RIGHT CARD ================= */
.clm-card-section {
  flex: 0.85;
  display: flex;
  flex-direction: column;
  align-self: center !important;
  align-items: center;
}

.clm-card {
  width: 100%;
  max-width: 400px;
  background: #ffffff;
  border-radius: 18px;
  padding: 38px 32px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.07);
}

.clm-card-header {
  margin-bottom: 24px;
}

.clm-card-title {
  font-size: 25px;
  font-weight: 800 !important;
  color: #0f172a;
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}

.clm-card-subtitle {
  font-size: 13.5px;
  font-weight: 400 !important;
  color: #64748b;
  margin: 0;
}

/* Error Banner */
.clm-err {
  background: #fef2f2;
  border: 1px solid #f87171;
  border-radius: 6px;
  padding: 10px 14px;
  font-size: 12px;
  font-weight: 500 !important;
  color: #b91c1c;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Inputs */
.clm-field {
  margin-bottom: 16px;
}

.clm-inp-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.clm-inp-icon {
  position: absolute;
  left: 14px;
  color: #64748b;
  display: flex;
  align-items: center;
  pointer-events: none;
}

.clm-inp {
  width: 100%;
  height: 48px;
  background: #f1f5f9;
  border: 1.5px solid transparent;
  border-radius: 8px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 400 !important;
  color: #0f172a;
  outline: none;
  transition: all 0.16s ease;
}

.clm-inp-has-icon {
  padding-left: 44px;
}

.clm-inp:focus {
  background: #ffffff;
  border-color: #ffd800;
  box-shadow: 0 0 0 3px rgba(254, 216, 0, 0.28);
}

.clm-inp::placeholder {
  color: #94a3b8;
  font-weight: 400 !important;
}

/* Action Button */
.clm-btn {
  width: 100%;
  height: 48px;
  background: #fedb00;
  border: none;
  border-radius: 8px;
  font-size: 14.5px;
  font-weight: 700 !important;
  color: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  margin-top: 10px;
  transition: background 0.15s ease, transform 0.1s ease;
}

.clm-btn:hover {
  background: #f2cb00;
  transform: translateY(-1px);
}

.clm-btn:active {
  transform: translateY(0);
}

.clm-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Divider */
.clm-separator {
  position: relative;
  text-align: center;
  margin: 20px 0;
}

.clm-separator::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  background: #e2e8f0;
}

.clm-separator span {
  position: relative;
  background: #ffffff;
  padding: 0 12px;
  font-size: 11px;
  font-weight: 500 !important;
  color: #94a3b8;
  letter-spacing: 0.05em;
}

/* SSO Button & Microsoft Logo */
.clm-sso-btn {
  width: 100%;
  height: 48px;
  background: #ffffff;
  border: 1.5px solid #0f172a;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600 !important;
  color: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  cursor: pointer;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.clm-ms-logo {
  flex-shrink: 0;
  display: block;
}

.clm-sso-btn:hover {
  background: #f8fafc;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

/* Support Help */
.clm-help-link {
  margin-top: 22px;
  text-align: center;
  font-size: 12.5px;
  font-weight: 400 !important;
  color: #64748b;
}

.clm-help-link a {
  color: #0265c2;
  font-weight: 600 !important;
  text-decoration: none;
}

.clm-help-link a:hover {
  text-decoration: underline;
}

/* ================= RESPONSIVE ================= */
@media (max-width: 992px) {
  .clm-login-viewport {
    min-height: 100vh;
    height: 100%;
    padding: 36px 24px;
  }

  .clm-login-container {
    flex-direction: column;
    align-items: center;
    gap: 36px;
    min-height: auto;
  }

  .clm-info-section {
    max-width: 100%;
    text-align: center;
    align-items: center;
  }

  .clm-headline {
    font-size: 32px;
  }

  .clm-brand-divider {
    margin: 0 auto 16px auto;
  }

  .clm-card-section {
    align-items: center;
    width: 100%;
  }

  .clm-copyright-desktop {
    display: none;
  }

  .clm-copyright-mobile {
    display: block;
    font-size: 11px;
    font-weight: 400 !important;
    color: #94a3b8;
    margin-top: 22px;
    text-align: center;
  }
}

@media (max-width: 520px) {
  .clm-login-viewport{
    min-height: 100vh;
    height: 100%
  }
  .clm-features-row {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .clm-feature-sep {
    display: none;
  }

  .clm-card {
    padding: 26px 20px;
  }
}
